-- PAPER-LEARN-PROBATION-SETTLE-1 part 6 of 9 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Settles 25 probationary direct paper learnings (ids 5227 to 5403 of the 225 read on 2026-11-04 23:00Z): each row was read in full (claim, lever, application and the model's apply signal) against the live fleet and given one disposition with its reason.
-- PAPER-LEARN-TRIAGE-1 parked them in probation because its catalogue held 6 mechanisms; the apply signal usually meant the model did not know the fleet already does this. Dispositions: already-in-place (mechanism named, existence read today), rejected (category and specific reason, with what would justify re-proposing), routed (to agent_issues 1000459 TRIGGER-FLAP-1 or goal external-impact-per-dollar).
-- Each goal PAPER-LEARN-<id> (DoD: the learning is settled) then completes on its next probe, and roadmap row GL-PAPER-LEARN-<id> verifies in the hourly loop. Revert one row: UPDATE paper_learnings SET fleet_status = 'probation' WHERE id = <id>.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_learnings SET fleet_status = (SELECT b.fleet_status FROM bak_20261105_c8_pl_06 b WHERE b.id = paper_learnings.id), status_note = (SELECT b.status_note FROM bak_20261105_c8_pl_06 b WHERE b.id = paper_learnings.id), updated_at = (SELECT b.updated_at FROM bak_20261105_c8_pl_06 b WHERE b.id = paper_learnings.id) WHERE id IN (SELECT id FROM bak_20261105_c8_pl_06)

CREATE TABLE IF NOT EXISTS bak_20261105_c8_pl_06 AS SELECT * FROM paper_learnings WHERE id IN (5227, 5229, 5231, 5235, 5236, 5237, 5238, 5279, 5290, 5292, 5293, 5297, 5300, 5303, 5304, 5305, 5307, 5333, 5334, 5335, 5349, 5372, 5401, 5402, 5403);

UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): The fleet labels proxies: OUTPUT-QUALITY-LEDGER-1 marks a rule-based score as proxy in output_quality_measures, never a target, and keeps outcome measures separate, and each metric row states its formula.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5227 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Trust credit rests on verified outcomes read from live probes and measurements; no credit from verification in a simplified or simulated context is shown. The baseline-of-plausibility remark is the paper''s statement about its own analogue. Re-propose with a credited outcome that was verified only in a simulation.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5229 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): CLAIM-INTEGRITY-1 holds unsupported past-tense empirical claims and CITE-FULLTEXT-1 grounds each paper on full texts; no published pipeline paper is shown to have claimed primacy wrongly. Re-propose with a published paper whose primacy claim was wrong.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5231 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): transient noise filing issues from single raw samples is the defect that issue measures; a smoothing or band is its remedy.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5235 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The low-SNR dead zone is the paper''s result about threshold tuning of a quantum readout; the fleet''s metrics are counts and rates over full tables and a metric whose signal is too noisy is handled by bands in TRIGGER-FLAP-1 (agent_issues 1000459), not by a separate SNR gate.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5236 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; birth): Closing and escalating use the issue''s own history, not fleet averages: each issue has its own contract class (issue-<id>) and probe verdict trail in remediation_verifications, and a state change is written to issue_lifecycle.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5237 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; retention): Raw event records are kept: decision_log, issue_lifecycle, goal_lifecycle and fleet_runs are append-only, and cold telemetry rows leave D1 only after a verified R2 object exists (COLD-TIER-1, #7239).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5238 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; replay): Changes are replayed against known inputs before they go live: migrations carry offline suites that run the migration on node:sqlite with the live table shapes (for example migrations/roadmap-self-maintain.test.mjs and migrations/personas-c-split.test.mjs), worker suites run on every pull request, and deploy probes baseline each worker before and after.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5279 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; bands): Early warning before a threshold exists: metric_registry carries a warning_band on 333 of 418 metrics and a kill_band on 257 (read 2026-11-05), so a metric alerts ahead of its breach.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5290 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Critical slowing down is the paper''s statistical early-warning signature for a phase transition; the fleet gives early warning through warning bands and measures recovery directly (issue_drain_ratio_24h, MTTR metrics). Re-propose with a breach that autocorrelation would have flagged earlier than the bands did.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5292 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; budget): Cost reduction cannot starve a loop: BUDGET-SOFT-ROUTE-1 states that a breached cap steers to a cheaper model or a smaller batch and never to a refusal, deferral queue or skipped run.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5293 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; pred): Every change ships with a refutable expectation: a pull request names the metric, direction and size it should move, an issue''s closing probe is written at birth, and a deploy probe baselined before the push reverts it if it regresses.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5297 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; modeleval): Fidelity per cost is how the model choice is made: qnfo-model-eval measures candidates on a fixed battery against the production control and the cheapest capable model is chosen (BUDGET-SOFT-ROUTE-1), with automatic revert on a quality drop.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5300 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Primary triggers are already fleet-level aggregates (metrics_in_breach, code_task_success_rate_30d, remedy_efficacy_30d, issue_drain_ratio_24h); no per-session micro-trigger exists whose false positives an aggregate would remove. Re-propose with such a trigger.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5303 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Minimum description length is the paper''s model-selection principle. A complexity penalty on doctrine or probes has no measured fleet defect behind it, and ENSEMBLE-POLICY-1 already keeps layers few and small.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5304 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Ratio versus weighted sum is the paper''s defence of its own efficiency measure; the fleet''s steering has one numeric parameter per cap (fleet_budget) and no accuracy-cost weights to make parameter-free.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5305 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Ordering artifacts in the paper''s static structure do not transfer: fleet trends are read over named windows of time-ordered rows. Re-propose with a fleet trend that vanished under a different window.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5307 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): activate at one threshold and clear only below another so a metric hovering at its boundary cannot churn tickets is the fix for the 167 reopens on 44 tickets that issue measures.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5333 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Scope and budget tier changes are rare, recorded in the canonical path and fleet_budget migrations; no flapping of a loop''s scope or tier is shown. The ticket-level flapping is owned by TRIGGER-FLAP-1 (agent_issues 1000459). Re-propose with a tier that oscillated.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5334 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; merge): Heavy protection runs where the threat is: scripts/review_gate.py classifies a diff and reads only the risky ones (auth, route, cache, trigger, migration, workflow) with two model families, and the cheapest models are used while a cap is breached.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5335 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; paper-convention): Registering a falsifiable prediction from each paper as a monitored metric is this paper''s convention for a mathematical claim (the GUE spacing); making it a field of every pipeline revision is a new hard gate with no measured defect. Re-propose with the share of published papers that state a prediction and no way to test it.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5349 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; paper-convention): Systematic evaluation against pre-registered alternative hypotheses is the physics paper''s remark on interferometry circularity; pipeline reviewers already come from disjoint families and the claim gate holds unsupported empirical claims. Re-propose with a reviewed paper whose presupposition went unchallenged.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5372 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; probecover): Probe coverage is audited against breach classes: every METRIC-TRIGGER issue is born with its trigger''s probe (trigger contract_probe_templates_v1), every failure mode has a detector contract, and the metrics issues_unprobed_60m (171) and unverified_blocker_claims (36) measure what is not covered.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5401 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; throughput): Drain capacity is tied to arrival: ISSUE-THROUGHPUT-1 measures issues closed against opened over 24 hours (issue_drain_ratio_24h 1.087 read 2026-11-04T23:34Z, target 1.5) and v_issue_family_throughput names each family with net inflow so a loop, probe or doer is built for it.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5402 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; conflicts): Conflicts with CRON-HOURLY-FLOOR-1 (owner directive 2026-10-19: no cron runs less than once an hour) and the 10-minute SLA resolution of QUEUE-SLA-1: a dormant loop that lengthens its interval would breach both. Idle loops are already cheap because each tick is bounded and the cheapest model runs while a cap is breached.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5403 AND fleet_status = 'probation';
